<?php
declare(strict_types=1);
function ensureConnectPlusTables(PDO $pdo): void {
 $pdo->exec("CREATE TABLE IF NOT EXISTS connectplus_config (id INT UNSIGNED NOT NULL AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,version VARCHAR(50) NOT NULL DEFAULT '0',update_url TEXT DEFAULT NULL,udp_port VARCHAR(255) DEFAULT '7300',contato VARCHAR(255) DEFAULT '',site VARCHAR(255) DEFAULT '',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_connectplus_user(user_id),KEY idx_connectplus_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE IF NOT EXISTS connectplus_servers (id INT UNSIGNED NOT NULL AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,color_name VARCHAR(30) DEFAULT '#ffffff',description VARCHAR(255) DEFAULT '',color_description VARCHAR(30) DEFAULT '#ffffff',type VARCHAR(50) DEFAULT 'PROXY',flag_url TEXT DEFAULT NULL,server_ip VARCHAR(255) DEFAULT '',check_user VARCHAR(255) DEFAULT '',server_port VARCHAR(20) DEFAULT '',ssl_port VARCHAR(20) DEFAULT '',username VARCHAR(255) DEFAULT '',password VARCHAR(255) DEFAULT '',payload TEXT DEFAULT NULL,proxy_ip VARCHAR(255) DEFAULT '',proxy_port VARCHAR(20) DEFAULT '',sni VARCHAR(255) DEFAULT '',path VARCHAR(255) DEFAULT '',color VARCHAR(30) DEFAULT '#0000ff',info VARCHAR(255) DEFAULT 'Proxy',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_cp_servers_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
}
function getConnectPlusConfig(PDO $pdo,int $uid):array{$s=$pdo->prepare('SELECT * FROM connectplus_config WHERE user_id=? LIMIT 1');$s->execute([$uid]);return $s->fetch()?:['version'=>'0','update_url'=>'','udp_port'=>'7300','contato'=>'','site'=>''];}
function getConnectPlusServers(PDO $pdo,int $uid):array{$s=$pdo->prepare('SELECT * FROM connectplus_servers WHERE user_id=? ORDER BY id');$s->execute([$uid]);return $s->fetchAll();}
function buildConnectPlusConfig(PDO $pdo,int $uid):array{$c=getConnectPlusConfig($pdo,$uid);$rows=getConnectPlusServers($pdo,$uid);$ps=preg_split('/[;,#,\s]+/',trim((string)$c['udp_port']),-1,PREG_SPLIT_NO_EMPTY)?:[];$ps=array_values(array_filter(array_map('trim',$ps),fn($p)=>ctype_digit($p)&&(int)$p>=1&&(int)$p<=65535));return ['Version'=>(string)$c['version'],'Update'=>(string)$c['update_url'],'UdpPort'=>implode(';',$ps),'Contato'=>(string)$c['contato'],'Site'=>(string)$c['site'],'Servers'=>array_map(fn($s)=>['Name'=>(string)$s['name'],'ColorName'=>(string)$s['color_name'],'Description'=>(string)$s['description'],'ColorDescription'=>(string)$s['color_description'],'TYPE'=>(string)$s['type'],'FLAG'=>(string)$s['flag_url'],'ServerIP'=>(string)$s['server_ip'],'CheckUser'=>(string)$s['check_user'],'ServerPort'=>(string)$s['server_port'],'SSLPort'=>(string)$s['ssl_port'],'USER'=>(string)$s['username'],'PASS'=>(string)$s['password'],'Payload'=>(string)$s['payload'],'ProxyIP'=>(string)$s['proxy_ip'],'ProxyPort'=>(string)$s['proxy_port'],'SNI'=>(string)$s['sni'],'Path'=>(string)$s['path'],'Color'=>(string)$s['color'],'Info'=>(string)$s['info']],$rows)];}
